import{_ as t,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-06-13 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-06-13 :: Ceph Performance Meeting","date":"2019-06-13T00:00:00.000Z","updated":"2019-06-14T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息传递","多点同步","IO环境引擎","数据缓存","AutoTuning","自动化测试","CBT","RocksDB数据布局"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-13_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-06-13_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-06-13_-_-_Ceph_Performance_Meeting.md"};function n(e,o,a,g,p,_){return l(),r("div",null,[...o[0]||(o[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Neha, Sage, Radek, Adams, Jason, Eric, Orlando, Roman, Mark Cogan, Tiago, Igor, Josh 等</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 项目进展</strong></p><ul><li><strong>Neha</strong>： 完成对 CBT 或病理学任务中新的客户端端点的支持，正在进行最终测试。</li><li><strong>Sage</strong>： 审查了 PG 映射缓存 PR，该 PR 提供了显著的性能提升。</li><li><strong>Radek</strong>： 优化输入缓冲区工厂，以改善 Crimson 的性能。</li><li><strong>Adams</strong>： 开发新的 shirt and blue 存储迭代，需要审查。</li><li><strong>Jason</strong>： 提交了异步消息 PR，降低了调用次数，并提高了性能。</li><li><strong>Eric</strong>： 进行多点同步公平性工作，已进入测试阶段。</li><li><strong>Roman</strong>： 进行 IO 环境引擎工作，需要重新审查。</li><li><strong>Mark Cogan</strong>： 进行分布式数据缓存 PR，已审查。</li><li><strong>Igor</strong>： 审查了 mall P PR，该 PR 提高了 Auto Tuning 的启动效率。</li><li><strong>Tiago</strong>： 进行分布式数据缓存 PR，已审查。</li></ul><p><strong>二、Ceph 测试平台（CBT）</strong></p><ul><li><strong>Neha</strong>： CBT 支持客户端端点，可以用于 Crimson 测试和夜间测试。</li><li><strong>讨论</strong>： 讨论了 CBT 的未来发展方向，包括： <ul><li>支持更多安装方法，例如 Ansible 后端。</li><li>自动发现集群信息。</li><li>支持容器化测试。</li><li>UI 和结果解析工作。</li></ul></li></ul><p><strong>三、RocksDB</strong></p><ul><li><strong>Orlando</strong>： 开发 CBT 图形和结果解析功能。</li><li><strong>Adams</strong>： RocksDB 的数据布局需要仔细考虑，以避免重复和性能问题。</li></ul><p><strong>四、其他</strong></p><ul><li><strong>讨论</strong>： 讨论了其他一些 PR 和议题，例如用户空间 IO 事件、MDS 缓存内存限制自动调整等。</li></ul><p><strong>五、行动计划</strong></p><ul><li>完成客户端端点支持测试。</li><li>完成 PG 映射缓存 PR 的审查。</li><li>完成输入缓冲区工厂优化。</li><li>完成 shirt and blue 存储迭代 PR 的审查。</li><li>继续优化异步消息。</li><li>完成多点同步公平性测试。</li><li>重新审查 IO 环境引擎 PR。</li><li>继续进行分布式数据缓存开发。</li><li>开发 CBT 图形和结果解析功能。</li><li>优化 RocksDB 数据布局。</li><li>其他成员：继续关注和参与 Ceph 项目开发。</li></ul>',14)])])}const u=t(s,[["render",n]]);export{c as __pageData,u as default};
